const resp = $json;
const text = (resp.content && resp.content[0] && resp.content[0].text) || '';
const m = text.match(/\{[\s\S]*\}/);
const SH = ['Новая заявка','Вопрос по заказу','Поставщик','Спам','Прочее'];
let shelf='Прочее', reason='не распарсилось';
if (m) { try { const o = JSON.parse(m[0]); shelf = SH.includes(o.shelf) ? o.shelf : (SH.find(s=>String(o.shelf||'').toLowerCase().includes(s.toLowerCase()))||'Прочее'); reason = String(o.reason||'').slice(0,500); } catch(e){} }
const name = $('Подготовить текст').item.json.name;
return { json: { name, shelf, reason } };
